  ('c24c0952-84b8-52e1-973f-436c766b9751', 'fp-google-ChIJJ2CD1mEddkgRAuOi9iSzBrk', 'rules.pushchair-play-areas', '{"kind":"pushchair","scope":"area","area":"Storytelling and play areas","coversCoreVisit":true,"text":"Pushchairs and buggies are not allowed in any storytelling or play areas. Buggy storage is available on site; bring a sling for a smaller baby."}'::jsonb, 'high', 'https://discover.org.uk/getting-here/', 'There is buggy parking available on our Ground Floor. We do not allow buggies and pushchairs in any of our s torytelling or play areas . If you have a smaller baby we recommend bringing a sling.', 'human_reviewed_official_page', '2026-10-08', '2026-11-07', 'human:aidan', 'active'),
  ('e8b5f786-3ca6-5348-9f49-c28c1550baec', 'fp-google-ChIJJ2CD1mEddkgRAuOi9iSzBrk', 'rules.pushchair-exception', '{"kind":"caution","scope":"venue","exceptionOf":"pushchair-play-areas","text":"If you have a particular reason to need a buggy (for example twin babies or a sleeping child), speak to the front of house team, who can advise and may be able to accommodate it."}'::jsonb, 'high', 'https://discover.org.uk/your-visit/faqs/', 'If you have a particular reason why you need a buggy with you – eg twin babies or a sleeping child – do speak to our front of house team who will be able to advise and accommodate your buggy where needed.', 'human_reviewed_official_page', '2026-10-08', '2026-11-07', 'human:aidan', 'active'),
